import{_ as t,o,c as i,a0 as n}from"./chunks/framework.lnbZLl6b.js";const a="/projects/aquilifer/screenshots/popup-connected.png",r="/projects/aquilifer/screenshots/popup-change-model.png",f=JSON.parse('{"title":"The toolbar popup","description":"","frontmatter":{},"headers":[],"relativePath":"docs/popup.md","filePath":"docs/popup.md"}'),s={name:"docs/popup.md"};function c(p,e,l,h,d,u){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="the-toolbar-popup" tabindex="-1">The toolbar popup <a class="header-anchor" href="#the-toolbar-popup" aria-label="Permalink to &quot;The toolbar popup&quot;">​</a></h1><p>Click the Aquilifer icon in your browser toolbar to open it: a quick-glance surface for what&#39;s connected and how close you are to your own limits, without opening full settings.</p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><p><img src="'+a+'" alt="The toolbar popup for a connected site: connection status, rate-limit bar and standing, a Disconnect button, and the provider list with status badges"></p><ul><li><strong>Every configured provider</strong>, with its current model, and a live indicator (a spinning icon) when a request to that provider is actually in flight right now.</li><li><strong>Which provider (if any) the current tab&#39;s site is connected to</strong>, and that connection&#39;s real rate-limit standing: how close it is to being blocked, right now, not just the configured threshold. If a site is close on its per-interface limit but looks fine on the global one (or vice versa; see <a href="/projects/aquilifer/docs/rate-limiting">Rate limiting</a>), the popup shows whichever one is actually closest to blocking, since that&#39;s the number that answers &quot;am I about to get rate-limited.&quot;</li><li><strong>A Disconnect button</strong> for the current site&#39;s connection. It revokes that connection immediately; the next request the site makes goes through the connect/approve flow again from scratch, the same as disconnecting it from Options&#39; Connected sites tab.</li></ul><h2 id="managing-providers-from-here" tabindex="-1">Managing providers from here <a class="header-anchor" href="#managing-providers-from-here" aria-label="Permalink to &quot;Managing providers from here&quot;">​</a></h2><p>A few things you&#39;d otherwise need Options open for:</p><ul><li><strong>Set default</strong>: change which provider new site connections default to.</li><li><strong>Change model</strong>: fetches that provider&#39;s available models on demand (not automatically every time you open the popup) and lets you pick a different one. Picking any model closes the dropdown back up, including re-picking the one that&#39;s already selected if you open it and decide not to change anything.</li></ul><p><img src="'+r+'" alt="The Change model dropdown open for a provider, listing its available models"></p><p>For anything not covered here (adding or removing providers, connected sites, rate-limit settings, history, the vault), see <a href="/projects/aquilifer/docs/providers">Providers</a> and the rest of the sidebar. The popup is a quick-glance surface, not a replacement for Options; when no providers are configured yet, it links straight there.</p>',10)])])}const m=t(s,[["render",c]]);export{f as __pageData,m as default};
